<template>
  <State
    :title="currentStatus.title"
    :description="currentStatus.description"
    :icon="status === 'geocoding' ? LocateIcon : Spinner"
    icon-class="size-16 w-16"
  >
    <Progress v-if="status === 'processing'" class="my-4" :model-value="import_progress" />
    <Progress v-if="status === 'indexing'" class="my-4" :model-value="indexing_progress" />
    <Progress v-if="status === 'geocoding'" class="my-4" :model-value="geocoding_progress" />
  </State>
</template>

<script lang="ts" setup>
import Spinner from '~/assets/icons/spinner.svg';
import { useProjectVoterDatabase } from '~/queries/project/edit/voterDatabase';
import { LocateIcon } from 'lucide-vue-next';

interface Props {
  status: 'pending' | 'processing' | 'indexing' | 'geocoding';
}

const statuses: ComputedRef<
  Record<'pending' | 'processing' | 'indexing' | 'geocoding', { title: string; description: string }>
> = computed(() => ({
  pending: { title: 'Pending', description: 'Voter database is pending processing. It should start shortly.' },
  processing: {
    title: `Importing (${import_progress.value.toFixed(2)}%)`,
    description: 'Voter database is being imported. This may take a few minutes.',
  },
  indexing: {
    title: `Indexing (${indexing_progress.value.toFixed(2)}%)`,
    description: 'Voter database is being indexed. This may take a few minutes.',
  },
  geocoding: {
    title: `Geocoding (${geocoding_progress.value.toFixed(2)}%)`,
    description: `Voter database is imported and ready for validations. Geocoding may take a while.`,
  },
}));

const props = defineProps<Props>();

const currentStatus = computed(() => statuses.value[props.status]);

const { projectVoterDatabase, refetch, projectId } = useProjectVoterDatabase();

useTimeoutPoll(async () => {
  await refetch().catch((error) => {
    console.error('Error refetching project voter database:', error);
  });
  const queryCache = useQueryCache();
  await queryCache.invalidateQueries({ key: ['project-edit-tabs-status', projectId.value] });
}, 10000);

const import_progress = computed(() => {
  if (projectVoterDatabase.value?.import_progress) {
    if (projectVoterDatabase.value.import_progress.total > 0)
      return (
        Math.round(
          (projectVoterDatabase.value.import_progress.value / projectVoterDatabase.value.import_progress.total) *
            100 *
            100
        ) / 100
      );
    else return 100.0;
  }
  return 0.0;
});

const indexing_progress = computed(() => {
  if (projectVoterDatabase.value?.indexing_progress) {
    if (projectVoterDatabase.value.indexing_progress.total > 0)
      return (
        Math.round(
          (projectVoterDatabase.value.indexing_progress.value / projectVoterDatabase.value.indexing_progress.total) *
            100 *
            100
        ) / 100
      );
    else return 100.0;
  }
  return 0.0;
});

const geocoding_progress = computed(() => {
  if (projectVoterDatabase.value?.geocoding_progress) {
    if (projectVoterDatabase.value.geocoding_progress.total > 0)
      return (
        Math.round(
          (projectVoterDatabase.value.geocoding_progress.value / projectVoterDatabase.value.geocoding_progress.total) *
            100 *
            100
        ) / 100
      );
    else return 100.0;
  }
  return 0.0;
});
</script>

<style lang="scss" scoped></style>
