<template>
  <ResponsiveTable>
    <ResponsiveTableHeader>
      <ResponsiveTableHead v-for="head in headers" :key="head" class="text-nowrap">{{
        snakeCaseToCapitalizedCase(head)
      }}</ResponsiveTableHead>
    </ResponsiveTableHeader>
    <ResponsiveTableBody>
      <ResponsiveTableRow v-for="(item, index) in items" :key="index">
        <ResponsiveTableCell
          v-for="value in processVoterInfoItem(item)"
          :key="value.key"
          :cols="2"
          :cols-sm="2"
          :label="snakeCaseToCapitalizedCase(value.key)"
        >
          {{ value.value }}
        </ResponsiveTableCell>
      </ResponsiveTableRow>
    </ResponsiveTableBody>
  </ResponsiveTable>
</template>

<script lang="ts" setup>
import type { ComApiModelProjectVoterDatabaseVoterInfo } from '~/client';
import _ from 'lodash';

interface Props {
  items: ComApiModelProjectVoterDatabaseVoterInfo[];
  headers: string[];
}

const props = defineProps<Props>();

function processVoterInfoItem(item: ComApiModelProjectVoterDatabaseVoterInfo) {
  const result: { key: string; value: any }[] = [];
  Object.entries(item).forEach(([key, value]) => {
    if (value !== null && value !== undefined) {
      result.push({ key, value });
    }
  });
  const sortedData = _.orderBy(result, (obj) => props.headers.indexOf(obj.key), 'asc');
  return sortedData;
}
</script>

<style lang="scss" scoped />
