import { getProjectVoterDatabaseConfiguration } from '~/client';

export const useProjectVoterDatabase = defineQuery(() => {
  const route = useRoute('projects-id');
  const projectId = computed(() => route.params.id as string);

  const {
    data: projectVoterDatabase,
    error,
    isLoading,
    refetch,
  } = useQuery({
    key: () => ['project-voter-database', projectId.value],
    query: () =>
      getProjectVoterDatabaseConfiguration({
        composable: '$fetch',
        path: { project_id: projectId.value },
      }),
    staleTime: 0,
    enabled: () =>
      (useRoute().name === 'projects-id-edit-voter-database' || useRoute().name === 'projects-id-voter-database') &&
      !!projectId.value,
  });

  return {
    projectId,
    projectVoterDatabase,
    status: computed(() => projectVoterDatabase.value?.status || null),
    error,
    isLoading,
    refetch,
  };
});
